CREATE VIEW app.public_rfq_specifications WITH (security_barrier = true) AS
SELECT s.id, s.rfq_item_id, s.definition_id, s.custom_name, s.value_text, s.value_number, s.value_boolean,
       s.value_min, s.value_max, s.uom_id, s.is_mandatory
FROM public.rfq_specifications s
JOIN public.rfq_items i ON i.id = s.rfq_item_id
JOIN app.public_rfqs p ON p.id = i.rfq_id;
